/* =====================================================================
   DistriMax - 05 Datos semilla (GENERADO, no editar a mano)
   Simula ~6 meses de operación con fechas relativas a GETDATE(),
   así los datos siempre se ven recientes sin importar cuándo se ejecute.
   Inventario, kardex, costo promedio y cartera quedan consistentes.
   ===================================================================== */
USE DistriMaxDB;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @H DATETIME = CAST(CAST(GETDATE() AS DATE) AS DATETIME);
BEGIN TRAN;

